    },
    {
      "id": "H3",
      "texto": "Alrededor de 32.000 usuarios se quedaron sin luz.",
      "paginas": ["P1", "P2", "P3", "P4", "P5", "P6", "P7"]
    },
    {
      "id": "H4",
      "texto": "Un técnico que pidió reserva dijo que el transformador llevaba 30 años sin cambiarse.",
