    },
    {
      "id": "H6",
      "texto": "En el barrio Villa Nueva, la junta de acción comunal contó 397 negocios que tuvieron pérdidas.",
      "paginas": ["P2"]
    },
    {
      "id": "H7",
      "texto": "En el barrio Primero de Mayo, la junta de acción comunal contó 76 negocios que tuvieron pérdidas.",
      "paginas": ["P2"]
    },
    {
      "id": "H8",
      "texto": "En el barrio La Floresta, la junta de acción comunal contó 341 negocios que tuvieron pérdidas.",
      "paginas": ["P3"]
    },
    {
      "id": "H9",
      "texto": "En el barrio El Carmen, la junta de acción comunal contó 249 negocios que tuvieron pérdidas.",
      "paginas": ["P4"]
    },
    {
      "id": "H10",
      "texto": "En el barrio Santa Rita, la junta de acción comunal contó 88 negocios que tuvieron pérdidas.",
